bool isPrime(int n) {
  if (n < 2) return false;
  for (int i = 2; i * i <= n; i++) {
    if (n % i == 0) return false;
  }
  return true;
}

void main() {
  print(isPrime(7));  // true
  print(isPrime(10)); // false
}

bool isPrime(int n) {
  if (n < 2) return false;
  return !List.generate(n - 2, (i) => i + 2).any((d) => n % d == 0);
}

